import{_ as o,a0 as i,w as p,s,I as n,x as e,a1 as a,A as r,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"有助於組織治理的 5 項開源原則 | LCTT x X-CMD","titleTemplate":false,"description":"有助於組織治理的 5 項開源原則 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有助於組織治理的 5 項開源原則 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有助於組織治理的 5 項開源原則 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230411.2 ⭐️⭐️ 5 open source principles that help organizational governance","title":"有助於組織治理的 5 項開源原則","tag":"202306","desc":""},"relativePath":"202306/20230411.2 ⭐️⭐️ 5 open source principles that help organizational governance.md","filePath":"[post].md"}'),u={name:"202306/20230411.2 ⭐️⭐️ 5 open source principles that help organizational governance.md"};function m(f,t,g,b,h,x){const l=i("Link");return p(),s("div",null,[t[24]||(t[24]=n("h1",{id:"有助於組織治理的-5-項開源原則",tabindex:"-1"},[e("有助於組織治理的 5 項開源原則 "),n("a",{class:"header-anchor",href:"#有助於組織治理的-5-項開源原則","aria-label":"Permalink to “有助於組織治理的 5 項開源原則”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/09/165636wl15bs9nstjdb4wj.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"採用基於開源原則的組織治理可以引導你的組織降低成本，降低技術債務，增加團隊協作，促進創新，最重要的是，推動你的組織共同前進。")],-1)),n("p",null,[t[1]||(t[1]=e("在我的職業生涯中，我很幸運地與許多不同規模的組織在各種項目上合作。所有這些項目的核心都是開源軟件，而且大多數人都對開源社區做出了力所能及的回報。我最近在一個大型組織內從事一個使用開源軟件的綠地項目。在項目的 MVP 階段結束後，該組織的領導層很想知道是什麼導致了項目的成功，以及他們如何將其應用到整個組織的其他團隊中。經過思考，我發現我們團隊的工作方式與開源社區和開發之間有相似之處。以下是對開源原則如何幫助組織節省資金、",-1)),a(l,{href:"https://enterprisersproject.com/article/2020/6/technical-debt-explained-plain-english?intcmp=7013a000002qLH8AAM"},{default:r(()=>[...t[0]||(t[0]=[e("減少技術債務",-1)])]),_:1}),t[2]||(t[2]=e(" 和打破內部孤島的一些見解。",-1))]),t[27]||(t[27]=n("h3",{id:"_1、更好地使用預算",tabindex:"-1"},[e("1、更好地使用預算 "),n("a",{class:"header-anchor",href:"#_1、更好地使用預算","aria-label":"Permalink to “1、更好地使用預算”"},"​")],-1)),n("p",null,[t[4]||(t[4]=e("我最近在佛羅里達 Drupal 營地發表了關於 ",-1)),a(l,{href:"https://noti.st/johnpicozzi/thgcPs/think-locally-build-globally-how-drupal-is-powering-headless-omni-channel-web-platforms"},{default:r(()=>[...t[3]||(t[3]=[e("無頭全渠道網絡平台",-1)])]),_:1}),t[5]||(t[5]=e(" 的演講。演講中強調的主要好處之一是如何通過實施這種網絡平台來節省資金。這個想法來自於開源軟件的開發。一個組織內的不同小組可以利用他們的預算來為一個核心軟件或平台貢獻特性或功能。他們還可以與其他小組合作，集中資金開發更復雜的功能。當功能開發完成後，它將被添加到核心軟件或平台中，供所有人使用。使用這種開源原則可以為組織內的團體提供互利。允許共享特性和功能，並集體從彼此的支出中獲益，可以改善軟件或平台。",-1))]),t[28]||(t[28]=d('<p>這種方法的另一個方面是可以節省開支，並允許持續改進，即對一個功能進行一次測試和開發，並重復使用它。在創建一個使用基於組件的設計系統作為起點的網絡平台時，我們經常看到這種情況。該平台的用户可以重複使用其他用户開發的組件或功能。通常，這些都已經經過了無數次的測試，比如用户體驗、可及性，甚至是安全測試。</p><p>這個簡單的想法在許多組織中面臨反對，因為個別團體覬覦和保護預算。團體不願意放棄他們的預算來支持核心軟件或平台。某些情況下，優先級和意見上的差異加劇了許多機構的孤島化。</p><h3 id="_2、減少技術債務" tabindex="-1">2、減少技術債務 <a class="header-anchor" href="#_2、減少技術債務" aria-label="Permalink to “2、減少技術債務”">​</a></h3><p>許多機構努力減少技術債務。實施一個全面的核心軟件或平台並使用開源原則，可以幫助減少技術債務。這可以通過允許開發團隊充分考慮一個功能不僅對建立它的小組，而且對更廣泛的組織有什麼影響。這一點，加上與組織內其他小組的合作，可以幫助減少未來重建或增加功能的需要。</p><p>有時，由於內部競爭，組織在這種合作和思考方面會有困難。一些公司培養了一種文化，即第一個建立一個功能或提出一個想法會得到獎勵。這可能會導致各小組不一起工作或分享想法，在組織內形成孤島，大大阻礙了創新。</p><h3 id="_3、更快進入市場" tabindex="-1">3、更快進入市場 <a class="header-anchor" href="#_3、更快進入市場" aria-label="Permalink to “3、更快進入市場”">​</a></h3><p>我經常聽到的一句話是“更快進入市場”。每個人都想更快、更容易地把他們的東西推出去。這通常是一個核心軟件或平台的好處，因為內部團體可以重用現有的、經過測試和驗證的特性和功能，而不是從頭開始建立自己的功能。如果你的團隊正在啓動一個項目，而它可以從 80% 的完成度而不是 0% 的完成度開始，你會這樣做嗎？我想是的。現在再加上為其他用户增加所需功能的超級英雄感覺。這是一個雙贏的結果！</p><h3 id="_4、發佈興奮點" tabindex="-1">4、發佈興奮點 <a class="header-anchor" href="#_4、發佈興奮點" aria-label="Permalink to “4、發佈興奮點”">​</a></h3><p>另一個可以幫助你的組織的偉大的開源原則是建立興奮的發佈時間表。當你的組織實施一個核心軟件或平台時，用户會對更新的時間進行投資。一個發佈時間表和路線圖可以向他們傳達這一點。這兩個工具可以幫助用户對新功能感到興奮，並相應地規劃他們自己的路線圖。這也有助於建立對其他團隊的欣賞，以及對建立新功能的團隊的自豪感。這可以統一一個組織，讓組織有團隊合作和成就感，同時提供結構和未來的計劃。</p><h3 id="_5、一個核心團隊和管理" tabindex="-1">5、一個核心團隊和管理 <a class="header-anchor" href="#_5、一個核心團隊和管理" aria-label="Permalink to “5、一個核心團隊和管理”">​</a></h3><p>我發現你需要兩個關鍵項目來克服上述障礙，並在你的組織內成功應用開源原則。這就是： 一個核心團隊和堅實的組織管理。一個核心團隊將允許一個小組來維護和管理你的組織的核心軟件或平台。它將支持該解決方案，並確保明智地增加新的特性和功能。這個團隊可以幫助減少內部團隊的成本，並告知各組路線圖的功能。核心團隊需要得到強大的組織治理的支持。這種治理將為組織內的小組提供一個共同的方向和組織支持，以取得成功。這種組織治理可以在幾個方面模仿開源的治理和原則。最基本和最高級別的原則是社區和為共同目標而工作的理念。</p><h3 id="開放式領導" tabindex="-1">開放式領導 <a class="header-anchor" href="#開放式領導" aria-label="Permalink to “開放式領導”">​</a></h3>',12)),n("p",null,[t[7]||(t[7]=e("採用基於 ",-1)),a(l,{href:"https://opensource.com/article/23/4/open-leadership-through-change"},{default:r(()=>[...t[6]||(t[6]=[e("開源原則",-1)])]),_:1}),t[8]||(t[8]=e(" 的組織治理可以引導你的組織降低成本，降低技術債務，增加團隊協作，促進創新，最重要的是，推動你的組織共同前進。",-1))]),t[29]||(t[29]=n("p",null,[n("em",null,"（題圖：MJ/be676bca-3cd3-4c21-9c6a-6cc5911c9c04）")],-1)),t[30]||(t[30]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),a(l,{href:"https://opensource.com/article/23/4/open-source-principals-organizational-governance"},{default:r(()=>[...t[9]||(t[9]=[e("https://opensource.com/article/23/4/open-source-principals-organizational-governance",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),a(l,{href:"https://opensource.com/users/johnpicozzi"},{default:r(()=>[...t[11]||(t[11]=[e("John E. Picozzi",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),a(l,{href:"https://github.com/lkxed/"},{default:r(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),a(l,{href:"https://github.com/geekpi"},{default:r(()=>[...t[13]||(t[13]=[e("geekpi",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const P=o(u,[["render",m]]);export{C as __pageData,P as default};
